from __future__ import annotations

import hashlib
import importlib.metadata as metadata
import json
import os
import subprocess
import sys
import time
from pathlib import Path
from typing import Any

import numpy as np


ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / ".tmp/b300-benchmarks"
PYTHON = str(ROOT / ".venv/bin/python")
ENV_KEYS = ("CUDA_VISIBLE_DEVICES", "JAX_PLATFORMS", "JAX_ENABLE_X64", "XLA_PYTHON_CLIENT_PREALLOCATE", "OMP_NUM_THREADS", "OPENBLAS_NUM_THREADS", "LD_LIBRARY_PATH", "XLA_FLAGS", "NCCL_P2P_DISABLE", "NCCL_NVLS_ENABLE", "UCX_MEMTYPE_CACHE")


def source_identity() -> str:
    paths = [ROOT / "pyproject.toml", ROOT / "uv.lock"]
    for directory in ("phydrax", "native"):
        paths.extend(path for path in (ROOT / directory).rglob("*") if path.is_file() and "__pycache__" not in path.parts and path.suffix in (".py", ".cpp", ".hpp", ".h", ".cu", ".cuh", ".cmake", ".patch", ".toml"))
    payload = [(str(path.relative_to(ROOT)), hashlib.sha256(path.read_bytes()).hexdigest()) for path in sorted(paths)]
    return hashlib.sha256(json.dumps(payload, separators=(",", ":")).encode()).hexdigest()


def save(record: dict[str, Any]) -> None:
    (OUT / "campaign.json").write_text(json.dumps(record, sort_keys=True, indent=2) + "\n")


def run(name: str, arguments: list[str], record: dict[str, Any]) -> dict[str, Any]:
    probe = subprocess.run(["nvidia-smi", "--query-compute-apps=pid,process_name,used_memory", "--format=csv,noheader"], capture_output=True, text=True, check=True)
    if probe.stdout.strip():
        raise RuntimeError(f"GPU is occupied before {name}: {probe.stdout}")
    command = [PYTHON, "-m", *arguments, "--output", str(OUT / f"{name}.json")]
    started = time.perf_counter()
    completed = subprocess.run(command, cwd=ROOT, capture_output=True, text=True, check=False)
    (OUT / f"{name}.log").write_text(completed.stdout + completed.stderr)
    record["commands"][name] = {"command": command, "returncode": completed.returncode, "seconds": time.perf_counter() - started, "gpu_processes_at_admission": probe.stdout, "source_identity": source_identity()}
    save(record)
    print(name, completed.returncode, record["commands"][name]["seconds"], flush=True)
    if completed.returncode:
        raise RuntimeError(f"{name} failed: {completed.stderr[-8000:]}")
    if record["commands"][name]["source_identity"] != record["source_identity"]:
        raise RuntimeError("Scientific source changed during the campaign")
    return json.loads((OUT / f"{name}.json").read_text())


def check_mace(report: dict[str, Any]) -> list[dict[str, Any]]:
    agreement = []
    for tier, reference_route, routes in (("coupling", "dense", {"dense", "streamed", "accelerated"}), ("model", "exact", {"exact", "trainable_accelerated", "streamed", "accelerated"})):
        grouped: dict[str, dict[str, dict[str, Any]]] = {}
        for row in report[tier]:
            if row.get("status") in ("failed", "refused"):
                raise RuntimeError(str(row))
            grouped.setdefault(json.dumps(row["case"], sort_keys=True), {})[row["route"]] = row
        for case, rows in grouped.items():
            if set(rows) != routes:
                raise RuntimeError(f"Missing {tier} routes: {case}")
            reference = rows[reference_route]
            for route, row in rows.items():
                expected_transforms = {"forward", "energy_forces", "strain_derivative", "force_loss_gradient", "hvp"} if tier == "coupling" else {"energy_forces", "strain_derivative", "hvp"}
                if tier == "model" and route in ("exact", "trainable_accelerated"):
                    expected_transforms.add("force_loss_gradient")
                if set(row["transforms"]) != expected_transforms:
                    raise RuntimeError(f"Missing {tier}/{route} transforms: {case}")
                for transform, result in row["transforms"].items():
                    if result["status"] != "measured":
                        raise RuntimeError(f"Unmeasured {tier}/{route}/{transform}: {result}")
                    if route == reference_route:
                        continue
                    wanted = reference["transforms"][transform]
                    tolerance = 2e-4 if row["case"]["precision"] == "float32" else 1e-10
                    maximum = 0.0
                    for actual_leaf, reference_leaf in zip(result["output_values"], wanted["output_values"], strict=True):
                        if actual_leaf["shape"] != reference_leaf["shape"] or actual_leaf["dtype"] != reference_leaf["dtype"]:
                            raise RuntimeError("MACE output structure differs from its reference")
                        actual = np.asarray(actual_leaf["values"])
                        expected = np.asarray(reference_leaf["values"])
                        np.testing.assert_allclose(actual, expected, rtol=tolerance, atol=tolerance)
                        maximum = max(maximum, float(np.max(np.abs(actual - expected))) if actual.size else 0.0)
                    agreement.append({"tier": tier, "case": row["case"], "route": route, "transform": transform, "rtol": tolerance, "atol": tolerance, "maximum_absolute_error": maximum})
    return agreement


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    record: dict[str, Any] = {"environment": {key: os.environ.get(key) for key in ENV_KEYS}, "packages": {item.metadata["Name"]: item.version for item in metadata.distributions()}, "source_identity": source_identity(), "commands": {}, "successful": False}
    save(record)
    for precision in ("float32", "float64"):
        spectral = run(f"spectral-{precision}", ["benchmarks.distributed_spectral", "--campaign", "one-device-functional", "--schedule", "slab", "--shape", "32,32,32", "--mesh-shape", "1", "--precision", precision, "--repeats", "3"], record)
        if not spectral["row"]["passed"]:
            raise RuntimeError("Spectral numerical gate failed")
    pic = run("pic-single", ["benchmarks.pic_distributed", "--routes", "reduced-slabs", "--parts", "1", "--cells-per-part", "16", "--slots-per-part", "128", "--packet-capacity", "32", "--warmup", "1", "--repeats", "3"], record)
    for route in pic["routes"].values():
        for kind in ("weak_scaling", "strong_scaling"):
            for row in route[kind]:
                if not row["physics"]["successful"] or row["physics"]["rejection_reason"] != 0:
                    raise RuntimeError("PIC physics gate failed")
                if kind == "strong_scaling" and row["field_difference_from_one_device"] != 0.0:
                    raise RuntimeError("Single-device PIC reference differs")
    for backend in ("jax", "pallas"):
        for precision in ("float32", "float64"):
            fmm = run(f"fmm-{backend}-{precision}", ["tools.particle_fmm_benchmarks", "--backend", backend, "--points", "32", "64", "--orders", "3", "--distributions", "uniform", "--dtype", precision, "--warmup", "1", "--repeats", "3"], record)
            if not fmm["passed"]:
                raise RuntimeError("FMM numerical gate failed")
    mace = run("mace", ["benchmarks.mace_execution_scaling", "--target", "cuda", "--nodes", "8", "16", "--degrees", "2", "--skews", "0", "--channels", "2", "--hidden-degrees", "1", "--edge-degrees", "1", "--precisions", "float32", "float64", "--receiver-tiles", "2", "--edge-tiles", "4", "--routes", "accelerated", "streamed", "dense", "--transforms", "forward", "energy_forces", "strain_derivative", "force_loss_gradient", "hvp", "--model-atoms", "4", "8", "--model-correlations", "2", "--model-species", "2", "--model-channels", "2", "--model-interactions", "1", "--model-routes", "exact", "trainable_accelerated", "streamed", "accelerated", "--model-transforms", "energy_forces", "strain_derivative", "force_loss_gradient", "hvp", "--host-initialization", "--repeats", "3", "--label", "b300-cuda"], record)
    record["mace_agreement"] = check_mace(mace)
    record["successful"] = True
    save(record)
    print("All benchmark numerical gates passed", flush=True)


if __name__ == "__main__":
    main()
